package com.smartlibrary;
import com.smartlibrary.model.*;import com.smartlibrary.service.*;import com.smartlibrary.repository.*;import com.smartlibrary.algorithms.string.*;import com.smartlibrary.algorithms.dp.*;import com.smartlibrary.algorithms.flow.*;import com.smartlibrary.algorithms.complexity.*;import com.smartlibrary.algorithms.randomized.*;import com.smartlibrary.algorithms.parallel.*;import com.smartlibrary.benchmark.*;import java.util.*;import java.nio.file.*;
public class Main {
 private static final Scanner in=new Scanner(System.in);private static LibraryService lib;
 public static void main(String[] args){lib=new LibraryService(new FileLibraryRepository(Path.of("data")));System.out.println("\n========== SMARTLIBRARY ==========");boolean run=true;while(run){System.out.println("\n1 Dashboard and Statistics\n2 Book Management\n3 Smart Pattern Search\n4 Intelligent Reading Planner\n5 Borrowing and Resource Allocation\n6 NP-Completeness and Optimization Lab\n7 Randomized Algorithms\n8 Parallel Algorithms\n9 Algorithm Performance Comparison\n10 Save Data\n0 Exit");switch(integer("Select option: ")){case 1->dashboard();case 2->books();case 3->pattern();case 4->planner();case 5->borrowing();case 6->complexity();case 7->randomized();case 8->parallel();case 9->benchmark();case 10->{lib.save();System.out.println("Saved.");}case 0->{lib.save();run=false;System.out.println("Goodbye.");}default->System.out.println("Choose a number from 0 to 10.");}}}
 private static int integer(String prompt){while(true){System.out.print(prompt);try{return Integer.parseInt(in.nextLine().trim());}catch(Exception e){System.out.println("Please enter a valid integer.");}}}private static String ask(String p){System.out.print(p);return in.nextLine().trim();}
 private static void show(Collection<Book> bs){System.out.printf("%-5s %-28s %-20s %-14s %-14s %s%n","ID","TITLE","AUTHOR","ISBN","CATEGORY","AVAILABLE/TOTAL");bs.forEach(System.out::println);}
 private static void dashboard(){System.out.println("Titles: "+lib.allBooks().size()+" | Copies: "+lib.allBooks().stream().mapToInt(Book::getTotalCopies).sum()+" | Available: "+lib.allBooks().stream().mapToInt(Book::getAvailableCopies).sum()+" | Active loans: "+lib.records().stream().filter(x->x.returnedOn()==null).count()+" | Reservations: "+lib.reservations().stream().filter(x->!x.fulfilled()).count());System.out.println("Popular books:");lib.popular().forEach(System.out::println);}
 private static void books(){System.out.println("1 Add  2 List  3 Search  4 Delete  5 Update");switch(integer("Choose: ")){case 1->{try{String id=ask("ID: "),t=ask("Title: "),a=ask("Author: "),isbn=ask("ISBN: "),c=ask("Category: "),d=ask("Description: ");int copies=integer("Copies: "),mins=integer("Reading minutes: "),value=integer("Learning value: ");lib.addBook(new Book(id,t,a,isbn,c,d,copies,copies,mins,value));lib.save();System.out.println("Added.");}catch(Exception e){System.out.println("Add failed: "+e.getMessage());}}case 2->show(lib.allBooks());case 3->show(lib.search(ask("Search: ")));case 4->{try{lib.deleteBook(ask("Book ID: "));lib.save();System.out.println("Deleted.");}catch(Exception e){System.out.println(e.getMessage());}}case 5->{try{Book b=lib.find(ask("Book ID: ")).orElseThrow();b.update(ask("Title: "),ask("Author: "),ask("ISBN: "),ask("Category: "),ask("Description: "),integer("Total copies: "),integer("Reading minutes: "),integer("Learning value: "));lib.save();System.out.println("Updated.");}catch(Exception e){System.out.println("Update failed: "+e.getMessage());}}default->System.out.println("Invalid option.");}}
 private static void pattern(){String p=ask("Pattern: ");int alg=integer("1 KMP 2 Z 3 Rabin-Karp 4 Suffix array/LCP 5 Suffix automaton 6 Compare: ");for(Book b:lib.allBooks()){String text=b.getTitle()+" — "+b.getDescription();switch(alg){case 1->{var r=KMP.search(text,p);if(!r.positions().isEmpty())System.out.println(b.getTitle()+" matches="+r.positions()+" comparisons="+r.comparisons()+" LPS="+Arrays.toString(r.lps()));}case 2->{var r=ZFunction.search(text,p);if(!r.positions().isEmpty())System.out.println(b.getTitle()+" matches="+r.positions()+" Z="+Arrays.toString(r.z()));}case 3->{var r=RabinKarp.search(text,p);if(!r.positions().isEmpty())System.out.println(b.getTitle()+" matches="+r.positions()+" hashes="+r.hashChecks()+" comparisons="+r.charComparisons());}case 4->{int[] sa=SuffixArray.build(text);var pos=SuffixArray.find(text,sa,p);if(!pos.isEmpty())System.out.println(b.getTitle()+" matches="+pos+" SA="+Arrays.toString(sa)+" LCP="+Arrays.toString(SuffixArray.lcp(text,sa)));}case 5->System.out.println(b.getTitle()+" contains="+new SuffixAutomaton(text).contains(p));case 6->AlgorithmBenchmark.run(text,p);default->{System.out.println("Invalid algorithm.");return;}}}System.out.println("KMP/Z: O(n+m); Rabin–Karp expected O(n+m); suffix array implementation is educational and slower than optimized construction.");}
 private static void planner(){try{var plan=BookKnapsack.solve(new ArrayList<>(lib.allBooks()),integer("Reading-time budget (minutes): "));System.out.println("Plan:");plan.books().forEach(System.out::println);System.out.println("Minutes="+plan.minutes()+", learning value="+plan.value()+". Complexity O(nB).");}catch(Exception e){System.out.println(e.getMessage());}}
 private static void borrowing(){System.out.println("1 Borrow 2 Return 3 Reserve 4 History 5 Max-flow demo");switch(integer("Choose: ")){case 1->{try{lib.borrow(ask("User ID (demo U001): "),ask("Book ID: "));System.out.println("Borrowed.");}catch(Exception e){System.out.println(e.getMessage());}}case 2->{try{lib.giveBack(ask("User ID: "),ask("Book ID: "));System.out.println("Returned.");}catch(Exception e){System.out.println(e.getMessage());}}case 3->{try{lib.reserve(ask("User ID: "),ask("Book ID: "));System.out.println("Reserved.");}catch(Exception e){System.out.println(e.getMessage());}}case 4->lib.records().forEach(System.out::println);case 5->{int[][] c={{0,3,2,0,0},{0,0,0,2,1},{0,0,0,1,2},{0,0,0,0,3},{0,0,0,0,0}};System.out.println("Max allocation flow="+EdmondsKarp.maxFlow(c,0,4));}default->System.out.println("Invalid option.");}}
 private static void complexity(){System.out.println("P: polynomial-time solvable. NP: solutions verifiable in polynomial time. NP-hard: at least as hard as every NP problem. NP-complete: in NP and NP-hard. P vs NP is unresolved.");var k=Optimization.knapsack(new int[]{2,3,4,5},new int[]{3,4,5,8},7);System.out.println("Exact knapsack: value="+k.value()+" indices="+k.indices()+"; O(2^n n).");int[][] edges={{0,1},{1,2},{2,3},{3,0},{1,3}};var cover=Optimization.vertexCoverApprox(4,edges);System.out.println("2-approx vertex cover="+cover+", valid="+Optimization.isVertexCover(cover,edges)+".");System.out.println("3-SAT → Vertex Cover reduction: variable gadgets are edges, clause gadgets are triangles, and occurrence vertices connect to opposite literals. Target cover size = variables + 2×clauses.");}
 private static void randomized(){switch(integer("1 Randomized QuickSort 2 Miller-Rabin: ")){case 1->{try{int[] a=Arrays.stream(ask("Integers separated by spaces: ").trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();RandomizedQuickSort.sort(a,42);System.out.println(Arrays.toString(a)+" (seed 42; always correctly sorted)");}catch(Exception e){System.out.println("Invalid integer list.");}}case 2->{try{long n=Long.parseLong(ask("Number: "));int rounds=integer("Rounds: ");System.out.println("Probably prime = "+MillerRabin.isProbablePrime(n,rounds,42)+"; theoretical false-positive bound 4^-rounds under independent uniform bases.");}catch(Exception e){System.out.println("Invalid input: "+e.getMessage());}}default->System.out.println("Invalid option.");}}
 private static void parallel(){try{int[] a=Arrays.stream(ask("Integers separated by spaces: ").trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();long t=System.nanoTime();long[] s=ParallelPrefixSum.sequential(a);long ts=System.nanoTime()-t;t=System.nanoTime();long[] p=ParallelPrefixSum.parallel(a);long tp=System.nanoTime()-t;System.out.println("Sequential="+Arrays.toString(s)+"\nParallel  ="+Arrays.toString(p)+"\nEqual="+Arrays.equals(s,p)+"; sequential ns="+ts+"; parallel ns="+tp);long[] l=Arrays.stream(a).asLongStream().toArray();System.out.println("Sum sequential="+ParallelReduce.sequentialSum(l)+", parallel="+ParallelReduce.parallelSum(l));}catch(Exception e){System.out.println("Invalid input.");}}
 private static void benchmark(){AlgorithmBenchmark.run(ask("Text: "),ask("Pattern: "));}
}
